from robot.api import logger


from ..exception import AliasError
from ute_common_admin.util import ensure_parent_dir_exists

from ..store import Store
from ..validators import IsString, IsOneOf, And, Or, IsInstance
from ..interfaces.base import BaseInterface
from .model import DeltaJSON


class DeltaInterface(BaseInterface):

    delta_store = Store()

    @classmethod
    def create_delta(cls, delta_id="default"):
        """Create new delta recommissioning JSON.

        :param string delta_id: ID of delta JSON.
        """
        IsString().check(delta_id)
        cls.delta_store.add(DeltaJSON(), delta_id)

    @classmethod
    def get_delta(cls, delta_id="default"):
        """Get serialized delta JSON.

        :param string delta_id: ID of delta JSON.
        """
        IsString().check(delta_id)
        return cls.delta_store.get(delta_id).serialize()

    @classmethod
    def save_delta(cls, target_file_name="delta.json", delta_id="default"):
        """Save serialized delta JSON to file.

        :param string target_file_name: target filename.
        :param string delta_id: ID of delta JSON.
        """
        IsString().check(target_file_name)
        IsString().check(delta_id)

        ensure_parent_dir_exists(target_file_name)
        with open(target_file_name, 'w') as delta_json:
            delta_json.write(cls.get_delta(delta_id))

    @classmethod
    def append_managed_object_to_delta(cls, dist_name, operation, delta_id="default"):
        """Append managed object to delta.

        :param string dist_name: Object dist name
        :param string operation: Parameter operation (create, update or delete)
        :param string delta_id: ID of delta JSON.
        """
        IsString().check(dist_name)
        And(IsString(), IsOneOf("update", "delete", "create")).check(operation)
        IsString().check(delta_id)

        cls.delta_store.get(delta_id).append_managed_object(dist_name, operation)

    @classmethod
    def append_parameter_update_to_delta(cls, dist_name, parameter, value, delta_id="default"):
        """Append parameter update to delta.

        :param string dist_name: Object distName
        :param string parameter: Name of parameter to update
        :param string/list value: value
        :param string delta_id: ID of delta JSON.
        """

        IsString().check(dist_name)
        IsString().check(parameter)
        IsString().check(delta_id)
        Or(IsString(value), IsInstance(value, list))

        cls.delta_store.get(delta_id).append_parameter_update(dist_name, parameter, value)

    @classmethod
    def append_parameter_delete_to_delta(cls, dist_name, parameter, delta_id="default"):
        """Append parameter delete to delta.

        :param string dist_name: Object distName
        :param string parameter: Name of parameter to delete
        :param string delta_id: ID of delta JSON.
        """
        IsString().check(dist_name)
        IsString().check(parameter)
        IsString().check(delta_id)

        cls.delta_store.get(delta_id).append_parameter_delete(dist_name, parameter)

    @classmethod
    def append_list_items_to_delta(cls, dist_name, list_name, *args, **kwargs):
        """Append simple type items to list

        :param string dist_name: Object distName.
        :param string list_name: List name (parameter of list type).
        :param string delta_id: ID of delta JSON (via kwargs).
        """
        delta_id = kwargs.get("delta_id", "default")

        IsString().check(dist_name)
        IsString().check(list_name)
        IsString().check(delta_id)

        cls.delta_store.get(delta_id).append_list_items(dist_name, list_name, *args)

    @classmethod
    def append_complex_item_to_delta(cls, dist_name, list_name, delta_id="default", **kwargs):
        """Append complex type item to list.

        :param string dist_name: Object distName
        :param string list_name: List name (parameter of list type).
        :param string delta_id: ID of delta JSON.
        """
        IsString().check(dist_name)
        IsString().check(list_name)
        IsString().check(delta_id)

        cls.delta_store.get(delta_id).append_complex_item(dist_name, list_name, **kwargs)

    @classmethod
    def remove_delta(cls, delta_id="default"):
        """Remove delta recommissioning JSON with given delta_id.

        :param string delta_id: ID of delta JSON.
        """
        IsString().check(delta_id)
        try:
            cls.delta_store.remove(delta_id)
        except AliasError:
            raise AliasError("Provided delta_id ({}) doesn't exist.".format(delta_id))

    @classmethod
    def remove_all_delta_id(cls):
        """Remove all delta recommissioning JSONs.
        """
        for delta_id in cls.delta_store.aliases:
            cls.remove_delta(delta_id)
            logger.info("delta_id {} removed".format(delta_id))
